using System.Text.Json; using dxpmt.Data; using dxpmt.Domain; using dxpmt.Services; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace dxpmt.Pages.Forms;
public sealed class F04Model(ApplicationDbContext database):PageModel { [BindProperty] public AsIsFlowFormModel Input{get;set;}=new(); public ImprovementCase Case{get;private set;}=null!; public List<WorkItem> WorkItems{get;private set;}=[]; public async Task<IActionResult> OnGetAsync(int caseId){if(!await Load(caseId))return NotFound();var f=await database.CaseForms.SingleOrDefaultAsync(x=>x.CaseId==caseId&&x.FormType==FormTypes.AsIsFlow&&x.Version==1);Input=Read(f?.ContentJson)??new AsIsFlowFormModel{Scope=Case.ScopeSummary};return Page();} public async Task<IActionResult> OnPostAsync(int caseId){if(!await Load(caseId))return NotFound();var now=DateTime.UtcNow;var f=await database.CaseForms.SingleOrDefaultAsync(x=>x.CaseId==caseId&&x.FormType==FormTypes.AsIsFlow&&x.Version==1);if(f is null){f=new CaseForm{CaseId=caseId,FormType=FormTypes.AsIsFlow,Version=1};database.CaseForms.Add(f);}f.ContentJson=JsonSerializer.Serialize(Input);f.UpdatedAt=now;Case.UpdatedAt=now;await database.SaveChangesAsync();return RedirectToPage(new{caseId});} private async Task<bool> Load(int id){var c=await database.Cases.SingleOrDefaultAsync(x=>x.Id==id);if(c is null)return false;Case=c;WorkItems=await database.WorkItems.Where(x=>x.CaseId==id&&x.WorkType==WorkItemTypes.AsIs&&!x.IsDeleted).OrderBy(x=>x.Sequence).ToListAsync();return true;} private static AsIsFlowFormModel? Read(string? json){try{return string.IsNullOrWhiteSpace(json)?null:JsonSerializer.Deserialize<AsIsFlowFormModel>(json);}catch{return null;}}}
